App.register({group:'people',label:'03 / 组织与身份',routes:[{path:'people/members',title:'成员管理',icon:'♙',permission:'people',render(){const members=DB.users.filter(u=>u.tenant===DB.state.tenant);return UI.page('PEOPLE / MEMBERS','成员与身份','员工账号、租户成员关系及项目资产移交。',UI.btn('＋ 邀请员工','member:invite','btn-primary'),`<div class="grid grid-3">${UI.metric('当前租户成员',members.length,'成员关系，不等于全局账号数','♙')}${UI.metric('正常账号',members.filter(m=>m.status==='正常').length,'可正常进入当前工作空间','✓')}${UI.metric('待邀请',members.filter(m=>m.status==='待邀请').length,'等待邀请确认','＋')}</div><div class="card section-gap"><div class="toolbar"><b class="small">当前租户成员</b><input class="search" data-filter placeholder="搜索姓名 / 邮箱"></div>${UI.table(['成员','租户角色','账号状态','负责项目','已交付作品','累计成本'],members.map(m=>`<tr><td><div class="entity"><div class="avatar">${m.name.slice(0,1)}</div><div><div class="entity-name">${m.name}</div><div class="entity-meta">${m.email}</div></div></div></td><td>${DB.roleNames[m.role]}</td><td>${UI.tag(m.status,m.status==='正常'?'green':'orange')}</td><td>${m.projects}</td><td>${m.delivered}</td><td class="mono">¥${m.cost.toLocaleString()}</td></tr>`))}</div><div class="notice warn section-gap">离职处理必须先移交项目负责人、未完成生产任务和资产责任关系；不得删除作品、剧本版本、成本及审计历史。</div>`);}} ,{path:'people/roles',title:'角色与权限',icon:'⌘',permission:'people',render(){return UI.page('PEOPLE / ACCESS CONTROL','角色与权限矩阵','权限按职责最小化授予；业务身份与租户上下文共同决定可访问范围。','',`<div class="card">${UI.table(['角色','职责边界','权限范围','关键限制'],DB.roles.map(r=>`<tr><td><b>${r.name}</b></td><td>${r.desc}</td><td>${UI.tag(r.scope,'blue')}</td><td>${r.id==='platform'?'不默认读取业务内容':r.id==='auditor'?'仅授权范围汇总 / 审计':r.id==='employee'?'本人及获授权项目':'按职责与操作审计'}</td></tr>`))}</div><div class="card section-gap"><div class="card-title">关键权限原则</div><div class="grid grid-2 section-gap"><div class="notice">平台运维身份只管理基础设施，不自动获得企业业务内容读取权限。</div><div class="notice">企业级管理员可以治理租户，但跨租户访问必须符合职责并留痕。</div><div class="notice">租户管理员只管理当前租户；经营审计角色不因查看汇总数据获得内容修改权。</div><div class="notice">普通员工在授权租户内独立制作，不需要专业岗位协作分工。</div></div></div>`);}}]});
